// The menu bar's protocol, both ends generated by `tool/prepare.sh`: Dart
// sends the menus as data whenever what they say changed, and Swift sends
// back the id of the item picked. See "The menu bar" in lib/ui/AGENTS.md.

// ignore_for_file: not_initialized_non_nullable_instance_field

import "package:pigeon/pigeon.dart";

@ConfigurePigeon(
  PigeonOptions(
    dartPackageName: "entoli_menu",
    dartOut: "packages/entoli_menu/lib/src/menu_contract.g.dart",
    swiftOut:
        "packages/entoli_menu/darwin/entoli_menu/Sources/entoli_menu/Contract/MenuContract.g.swift",
  ),
)
/// What the platform itself does from a menu: macOS's alone, iPadOS having
/// its own already.
enum NativeSystemItem {
  services,
  hide,
  hideOthers,
  showAll,
  quit,
  toggleFullScreen,
  minimize,
  zoom,
  arrangeInFront,
}

/// One item: [key] is the character typed with the chord key, lower case.
class NativeMenuItem {
  NativeMenuItem({
    required this.id,
    required this.title,
    this.key,
    this.shift = false,
    this.alt = false,
    this.enabled = true,
  });

  String id;
  String title;
  String? key;
  bool shift;
  bool alt;
  bool enabled;
}

/// One menu: its items in groups, a separator between each, and the
/// platform's own after them.
class NativeMenu {
  NativeMenu({
    required this.title,
    this.groups = const [],
    this.system = const [],
  });

  String title;
  List<List<NativeMenuItem>> groups;
  List<NativeSystemItem> system;
}

@HostApi()
abstract class NativeMenuBar {
  /// The whole bar, replacing what was there. The first menu is the app's.
  void show(List<NativeMenu> menus);
}

@FlutterApi()
abstract class NativeMenuPicks {
  void picked(String id);
}
